function [rho, t, mmol, n_o] = exponential_atm(alt_km)
%EXPONENTIAL_ATM  atmos.exponential(alt_km): the density [kg/m^3], temperature [K], mean molar mass [kg/kmol] and number density taken
%   as atomic O [1/m^3] at a geodetic altitude [km] (below 0, at 0).
%   alt_km: real[1] (passed a plain number)
%   returns rho: real[1] (passed a plain number)
%   returns t: real[1] (passed a plain number)
%   returns mmol: real[1] (passed a plain number)
%   returns n_o: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rho = 0;
    t = 0;
    mmol = 0;
    n_o = 0;
    h = alt_km;
    if (h < 0)
        h = 0;
    end
    [h0, rho0, hs] = asils.models.env.atmosphere((h * 1000));
    rho = ((rho0 / 1) * exp(((-((h - (h0 / 1000)))) / (hs / 1000))));
    t = (1000 - ((1000 - 186) * exp(((-((asils.pc.fmax(h, 90) - 90))) / 70))));
    mmol = asils.models.expatmos.mean_molar_mass(h);
    na = (6.02214076e+23 * 1000);
    n_o = ((rho * na) / mmol);
end
